from itertools import permutations

def claims_for(g, include_markers=False):
    R,C=len(g),len(g[0]); claims=[]
    colors=sorted({v for row in g for v in row if v not in (0,2,4)})
    for axis in ('h','v'):
        n=R if axis=='h' else C
        m=C if axis=='h' else R
        for i in range(n):
            arr=[g[i][j] if axis=='h' else g[j][i] for j in range(m)]
            for col in colors:
                inds=[j for j,x in enumerate(arr) if x==col]
                if len(inds)>=2:
                    lo,hi=min(inds),max(inds)
                    if include_markers:
                        # include contiguous 2s just outside and 2s within anchor span
                        while lo>0 and arr[lo-1]==2: lo-=1
                        while hi+1<m and arr[hi+1]==2: hi+=1
                        # if markers bracket anchors, include them
                        ms=[j for j,x in enumerate(arr) if x==2]
                        if len(ms)>=2:
                            for a in ms:
                                for b in ms:
                                    if a<min(inds) and b>max(inds): lo=min(lo,a);hi=max(hi,b)
                    if axis=='h': cells=[(i,j) for j in range(lo,hi+1)]
                    else: cells=[(j,i) for j in range(lo,hi+1)]
                    claims.append((axis,i,col,cells,lo,hi))
    return claims

def apply_claims(g, order_axis=('h','v'), color_order=None, include_markers=False):
    R,C=len(g),len(g[0]); out=[r[:] for r in g]
    claims=claims_for(g,include_markers)
    if color_order is None: color_order=sorted({x[2] for x in claims})
    # Apply all claims by orientation, then color; for same line/color no issue
    for ax in order_axis:
      for c in color_order:
        for claim in claims:
          axis,i,col,cells,*_=claim
          if axis==ax and col==c:
            for r,j in cells: out[r][j]=c
    return out

