def gap1_fill(g, collision='min'):
    R,C=len(g),len(g[0]); out=[r[:] for r in g]
    offers={}
    for r in range(R):
      for c in range(C-2):
        for color in set([g[r][c],g[r][c+2]]):
          if color not in (0,2,4) and g[r][c]==color==g[r][c+2]: offers.setdefault((r,c+1),set()).add(color)
    for c in range(C):
      for r in range(R-2):
        for color in set([g[r][c],g[r+2][c]]):
          if color not in (0,2,4) and g[r][c]==color==g[r+2][c]: offers.setdefault((r+1,c),set()).add(color)
    for (r,c), colors in offers.items():
      if collision=='min': chosen=min(colors)
      elif collision=='max': chosen=max(colors)
      elif collision=='vertical':
        vv=[]
        for cc in [c]:
          if r>0 and r+1<R and g[r-1][cc]==g[r+1][cc] and g[r-1][cc] not in (0,2,4): vv.append(g[r-1][cc])
        chosen=vv[0] if vv else min(colors)
      else: chosen=next(iter(colors))
      out[r][c]=chosen
    return out,offers
